import { Controller } from '@nestjs/common';

// 이 기능은 화면만 만든다.
// 연차 신청 API(POST /attendance-requests)와 현황 조회 API(GET /attendance-requests)는 다른 기능이 만든다.
@Controller('api/v1')
export class FnSfr01810Controller {}

