import { useState } from 'react';
import { Badge, Band, DataTable, DateInput, DateText, Drawer, Field, Filters, Form, LookupSelect, Pager, RefName, Select, TextInput, Tiles, call, useData } from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 10;

const STATUS_OPTIONS: [string, string][] = [
  ['기안', '기안'],
  ['결재대기', '결재대기'],
  ['진행중', '진행중'],
  ['승인', '승인'],
  ['보류', '보류'],
  ['반려', '반려'],
  ['회수', '회수'],
  ['완료', '완료'],
];

export default function FnSfr01810Page({ role, notify }: PageProps) {
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [attendanceTypeId, setAttendanceTypeId] = useState<number | string>('');
  const [approvalStatus, setApprovalStatus] = useState('');
  const [applied, setApplied] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);
  const [form, setForm] = useState<Row>({});

  const list = useData<Page>(
    () => call<Page>('GET', '/attendance-requests', role, undefined, { ...applied, page, size: SIZE }),
    [role, applied, page],
  );
  const pending = useData<Page>(
    () => call<Page>('GET', '/attendance-requests', role, undefined, { approvalStatus: '결재대기', page: 0, size: 5 }),
    [role],
  );

  const search = () => {
    setPage(0);
    setApplied({ employeeId, attendanceTypeId, approvalStatus });
  };

  const reset = () => {
    setEmployeeId('');
    setAttendanceTypeId('');
    setApprovalStatus('');
    setPage(0);
    setApplied({});
  };

  const setField = (key: string, value: unknown) => {
    setForm((prev) => ({ ...prev, [key]: value }));
  };

  const openCreate = () => {
    setForm({});
    setCreating(true);
  };

  const submit = async () => {
    if (!form.attendanceTypeId) {
      throw new Error('근태항목을 선택하세요.');
    }
    if (!form.startDate || !form.endDate) {
      throw new Error('시작일과 종료일을 입력하세요.');
    }
    if (String(form.endDate) < String(form.startDate)) {
      throw new Error('종료일은 시작일 이후여야 합니다.');
    }
    await call('POST', '/attendance-requests', role, {
      attendanceTypeId: form.attendanceTypeId,
      startDate: form.startDate,
      endDate: form.endDate,
      reason: form.reason,
    });
    notify('연차 신청을 등록하고 결재 상신을 요청했습니다.');
    setCreating(false);
    setPage(0);
    list.reload();
    pending.reload();
  };

  const rows = list.data?.items ?? [];
  const pendingRows = pending.data?.items ?? [];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>신청 현황</h2>
        <Tiles
          items={[
            ['조회 건수', list.data?.total ?? 0],
            ['결재 대기', pending.data?.total ?? 0],
          ]}
        />
      </section>

      <section className="box span-8">
        <h2>연차 사용내역</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="신청자">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
          </Field>
          <Field label="근태항목">
            <LookupSelect table="attendance_type" role={role} value={attendanceTypeId} onChange={setAttendanceTypeId} />
          </Field>
          <Field label="결재 진행 상태">
            <Select value={approvalStatus} onChange={setApprovalStatus} options={STATUS_OPTIONS} />
          </Field>
        </Filters>
        <Band total={list.data?.total}>
          <button type="button" onClick={openCreate}>연차 신청</button>
        </Band>
        {list.error ? <p>{list.error}</p> : null}
        <DataTable
          rows={rows}
          onRowClick={(row) => setDetail(row)}
          empty="조회된 신청 내역이 없습니다."
          columns={[
            { key: 'employeeId', label: '신청자', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
            { key: 'attendanceTypeId', label: '근태항목', render: (r) => <RefName table="attendance_type" role={role} value={r.attendanceTypeId} /> },
            { key: 'startDate', label: '시작일', render: (r) => <DateText value={r.startDate} /> },
            { key: 'endDate', label: '종료일', render: (r) => <DateText value={r.endDate} /> },
            { key: 'approvalStatus', label: '결재 진행 상태', render: (r) => <Badge value={r.approvalStatus} /> },
          ]}
        />
        <Pager page={page} size={SIZE} total={list.data?.total ?? 0} onPage={setPage} />
      </section>

      <section className="box span-4">
        <h2>처리 대기</h2>
        <DataTable
          rows={pendingRows}
          onRowClick={(row) => setDetail(row)}
          empty="결재 대기 건이 없습니다."
          columns={[
            { key: 'employeeId', label: '신청자', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
            { key: 'startDate', label: '시작일', render: (r) => <DateText value={r.startDate} /> },
            { key: 'approvalStatus', label: '상태', render: (r) => <Badge value={r.approvalStatus} /> },
          ]}
        />
      </section>

      {detail ? (
        <Drawer title="신청 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['신청자', <RefName table="employee" role={role} value={detail.employeeId} />],
              ['근태항목', <RefName table="attendance_type" role={role} value={detail.attendanceTypeId} />],
              ['시작일', <DateText value={detail.startDate} />],
              ['종료일', <DateText value={detail.endDate} />],
              ['사유', String(detail.reason ?? '')],
              ['결재 진행 상태', <Badge value={detail.approvalStatus} />],
            ]}
          />
        </Drawer>
      ) : null}

      {creating ? (
        <Drawer title="연차 신청" onClose={() => setCreating(false)}>
          <Form onSubmit={submit} submit="신청 및 결재 상신">
            <Field label="근태항목" required>
              <LookupSelect table="attendance_type" role={role} value={form.attendanceTypeId} onChange={(v) => setField('attendanceTypeId', v)} />
            </Field>
            <Field label="시작일" required>
              <DateInput value={form.startDate} onChange={(v) => setField('startDate', v)} />
            </Field>
            <Field label="종료일" required>
              <DateInput value={form.endDate} onChange={(v) => setField('endDate', v)} />
            </Field>
            <Field label="사유" wide>
              <TextInput multiline value={form.reason} onChange={(v) => setField('reason', v)} />
            </Field>
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
